import{_ as a,o as t,c as r,ae as o}from"./chunks/framework.Dn6zxbF8.js";const d=JSON.parse(`{"title":"Audiences: naming the organization's own people","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/audiences.md","filePath":"adrs/1008684393/references/audiences.md"}`),s={name:"adrs/1008684393/references/audiences.md"};function n(i,e,l,c,u,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="audiences-naming-the-organization-s-own-people" tabindex="-1">Audiences: naming the organization&#39;s own people <a class="header-anchor" href="#audiences-naming-the-organization-s-own-people" aria-label="Permalink to &quot;Audiences: naming the organization&#39;s own people&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-12.</p><h2 id="separate-axes" tabindex="-1">Separate axes <a class="header-anchor" href="#separate-axes" aria-label="Permalink to &quot;Separate axes&quot;">​</a></h2><p>Vendors keep three questions apart: who a person is, what they may do, and where an application can be reached.</p><ul><li>Who: AWS divides human identities into &quot;workforce, third parties, and users&quot;, where &quot;users are the consumers of your applications&quot; (<a href="https://docs.aws.amazon.com/wellarchitected/latest/security-pillar/identity-management.html" target="_blank" rel="noreferrer">Identity management</a>). Microsoft Entra says &quot;a workforce tenant configuration is for your employees, internal business apps, and other organizational resources&quot; (<a href="https://learn.microsoft.com/entra/external-id/tenant-configurations" target="_blank" rel="noreferrer">Tenant configurations</a>). Auth0 names the scenario &quot;B2E (Business to Employees)&quot; (<a href="https://auth0.com/docs/get-started/architecture-scenarios/b2e" target="_blank" rel="noreferrer">B2E</a>).</li><li>What: support and finance people still hold roles named admin, such as Google Workspace&#39;s &quot;Help Desk Admin&quot; (<a href="https://knowledge.workspace.google.com/admin/users/prebuilt-administrator-roles" target="_blank" rel="noreferrer">Prebuilt administrator roles</a>) and Microsoft&#39;s &quot;payroll administrators&quot; (<a href="https://learn.microsoft.com/security/privileged-access-workstations/privileged-access-security-levels" target="_blank" rel="noreferrer">Security levels</a>).</li><li>Where: Cloudflare Access describes &quot;internal applications that you host in your own environment&quot; (<a href="https://developers.cloudflare.com/cloudflare-one/access-controls/applications/http-apps/" target="_blank" rel="noreferrer">Self-hosted applications</a>).</li></ul><p>The ADR&#39;s audiences answer who is calling. Roles answer what they may do, so admin and support are roles inside the Internal audience, not audiences.</p><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p>In products with customers of their own, admin means the customer&#39;s administrator:</p><ul><li>Stripe: &quot;Administrator: This role is for anyone who needs similar access as the account owner&quot;, next to a customer-side &quot;Support Specialist&quot; (<a href="https://docs.stripe.com/get-started/account/teams/roles" target="_blank" rel="noreferrer">Roles</a>).</li><li>Atlassian: &quot;An organization admin is the highest level of admin&quot; (<a href="https://support.atlassian.com/user-management/docs/what-are-the-different-types-of-admin-roles/" target="_blank" rel="noreferrer">Admin roles</a>).</li><li>Zendesk: &quot;Agents, admins, and the account owner are all team members&quot;, all on the customer&#39;s side (<a href="https://support.zendesk.com/hc/en-us/articles/4408883763866" target="_blank" rel="noreferrer">Team member roles</a>).</li></ul><p>Naming the organization&#39;s own people Admin would collide with every such customer role.</p><h2 id="operator" tabindex="-1">Operator <a class="header-anchor" href="#operator" aria-label="Permalink to &quot;Operator&quot;">​</a></h2><p>Operator names platform engineers or software, never business staff:</p><ul><li>Kubernetes defines a cluster operator as &quot;a person who configures, controls, and monitors clusters&quot; and warns that &quot;cluster operators are different from the Operator pattern&quot; (<a href="https://kubernetes.io/docs/reference/glossary/?all=true" target="_blank" rel="noreferrer">Glossary</a>), in which &quot;operators are software extensions to Kubernetes&quot; (<a href="https://kubernetes.io/docs/concepts/extend-kubernetes/operator/" target="_blank" rel="noreferrer">Operator pattern</a>).</li><li>AWS&#39;s workforce &quot;includes administrators, developers, and operators&quot; who &quot;manage, build, and operate your AWS resources&quot; (<a href="https://docs.aws.amazon.com/wellarchitected/latest/security-pillar/identity-management.html" target="_blank" rel="noreferrer">Identity management</a>).</li><li>Google&#39;s SRE book uses &quot;human operators&quot; for the people running production (<a href="https://sre.google/sre-book/automation-at-google/" target="_blank" rel="noreferrer">Automation at Google</a>).</li></ul><h2 id="staff" tabindex="-1">Staff <a class="header-anchor" href="#staff" aria-label="Permalink to &quot;Staff&quot;">​</a></h2><p>Staff points both ways. Shopify&#39;s staff accounts belong to the merchant: &quot;you and your staff members can access the Shopify admin&quot; (<a href="https://help.shopify.com/en/manual/shopify-admin" target="_blank" rel="noreferrer">Shopify admin</a>). Django&#39;s <code>is_staff</code> &quot;designates whether the user can log into this admin site&quot; (<a href="https://github.com/django/django/blob/main/django/contrib/auth/models.py" target="_blank" rel="noreferrer">source</a>). Vendors describing their own people put their name first: &quot;GitHub personnel will not access private repository content without your consent&quot; (<a href="https://docs.github.com/en/site-policy/github-terms/github-terms-of-service" target="_blank" rel="noreferrer">Terms of Service</a>), &quot;Atlassian staff that access and process personal data&quot; (<a href="https://www.atlassian.com/trust/security/security-practices" target="_blank" rel="noreferrer">Security practices</a>).</p><h2 id="internal" tabindex="-1">Internal <a class="header-anchor" href="#internal" aria-label="Permalink to &quot;Internal&quot;">​</a></h2><p>&quot;Internal tools&quot; is the common name for what the organization&#39;s own people use. Retool describes itself as a way to &quot;build internal software&quot; and found that &quot;operations teams were the most popular&quot; audience for them (<a href="https://retool.com/blog/state-of-internal-tools-2022" target="_blank" rel="noreferrer">State of internal tools 2022</a>). No product surveyed uses internal for a customer&#39;s own people.</p><p>Internal also names network reach, as in an internal load balancer (<a href="./gcp.html#exposure">Google Cloud research</a>), so the ADR uses it only for people and describes reach in other words.</p><h2 id="platform" tabindex="-1">Platform <a class="header-anchor" href="#platform" aria-label="Permalink to &quot;Platform&quot;">​</a></h2><p>No provider names a level for the platform&#39;s own callers, such as the kubelet or load balancer health checks. Gateway API comes closest with personas, not levels (<a href="./kubernetes.html#exposure">Kubernetes research</a>).</p>',20)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
